(() => {
  'use strict';
  const M=window.Miam, E=M.esc, F=M.money;
  const role=document.body.dataset.role;
  let user=M.current();
  if(!user){location.replace('connexion.html');return;}
  if(user.role!==role){location.replace(`${user.role}.html`);return;}
  const root=document.querySelector('#app'),dialog=document.querySelector('#workspace-dialog');
  let data,view,filters={q:'',category:'Tous',status:'toutes',period:7},checkout={mode:'surplace',usePoints:false},lastFocus,pendingPayment=null;
  const paths={home:'M3 11 12 3l9 8M5 10v11h5v-7h4v7h5V10',menu:'M4 3h16v18H4zM8 7h8M8 12h8M8 17h5',bag:'M4 8h16l1 13H3L4 8ZM8 9V6a4 4 0 0 1 8 0v3',orders:'M6 3h12v18H6zM9 7h6M9 11h6M9 15h4',gift:'M3 8h18v5H3zM5 13v8h14v-8M12 8v13M12 8C3 8 4 1 8 3l4 5ZM12 8c9 0 8-7 4-5l-4 5Z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M20 21v-2a4 4 0 0 0-3-4M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM17 4a4 4 0 0 1 0 7',calendar:'M4 5h16v16H4zM8 2v6M16 2v6M4 10h16',message:'M3 3h18v14H8l-5 4V3ZM7 7h10M7 12h7',award:'M8 3h8v6a4 4 0 0 1-8 0V3ZM8 5H3v3a4 4 0 0 0 5 4M16 5h5v3a4 4 0 0 1-5 4M12 13v7M8 21h8',profile:'M4 21v-2a8 8 0 0 1 16 0v2M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z',chart:'M3 3v18h18M7 16v-5M12 16V7M17 16V4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',logout:'M9 3H3v18h6M13 7l5 5-5 5M7 12h14',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14Zm5 12 6 6',arrow:'M3 12h18m-7-7 7 7-7 7',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 4v6l4 2',check:'m4 12 5 5L20 6',plus:'M12 4v16M4 12h16'};
  const icon=name=>`<svg class="ui-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.menu}"/></svg>`;
  const menus={
    etudiant:[['accueil','Mon quotidien','home'],['menu','La carte','menu'],['panier','Mon panier','bag'],['commandes','Mes commandes','orders'],['fidelite','Ma fidélité','gift'],['parrainage','Inviter mes amis','users'],['evenements','Offres & événements','calendar'],['reclamations','Mes réclamations','message'],['classement','Le top des gourmands','award'],['profil','Mon profil','profile']],
    employe:[['accueil','Vue du service','home'],['commandes','Les commandes','orders'],['menu','Disponibilité des plats','menu'],['reclamations','Réclamations','message'],['statistiques','La semaine en chiffres','chart']],
    gerant:[['accueil','Vue d’ensemble','home'],['commandes','Suivi des commandes','orders'],['menu','La carte du jour','menu'],['equipe','Mon équipe','users'],['reclamations','Réclamations','message'],['statistiques','Statistiques','chart']],
    admin:[['accueil','Vue d’ensemble','home'],['commandes','Toutes les commandes','orders'],['menu','Gestion de la carte','menu'],['equipe','Gestion des comptes','users'],['promotions','Offres & événements','calendar'],['reclamations','Réclamations','message'],['statistiques','Statistiques','chart'],['parametres','Paramètres','settings']]
  };
  const title=()=>menus[role].find(m=>m[0]===view)?.[1]||'Mon espace';
  const ownOrders=()=>data.orders.filter(o=>o.userId===user.id);
  const person=id=>data.users.find(u=>u.id===id)?.name||'Ancien compte';
  const status=o=>`<span class="status status-${o.status}"><i></i>${M.statuses[o.status]}</span>`;
  const complaintStatus={ouverte:'Ouverte',validation:'À valider',resolue:'Résolue'};
  const empty=(title,text,link='',label='Découvrir la carte')=>`<div class="empty-state">${icon('bag')}<h3>${title}</h3><p>${text}</p>${link?`<a class="primary-btn" href="${link}">${label} →</a>`:''}</div>`;
  const field=(label,name,value='',type='text',extra='')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${E(value)}" ${extra}></label>`;
  const options=(items,current)=>items.map(x=>`<option value="${E(x)}" ${x===current?'selected':''}>${E(x)}</option>`).join('');
  function toast(text){const node=document.querySelector('#app-toast');node.textContent=text;node.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.classList.remove('visible'),3500);}
  function modal(title,body){lastFocus=document.activeElement;document.querySelector('#modal-content').innerHTML=`<span class="overline">MON MIAM MIAM</span><h2 id="modal-title">${E(title)}</h2>${body}`;dialog.showModal();}
  function close(){dialog.close();}
  dialog.querySelector('.modal-close').addEventListener('click',close);
  dialog.addEventListener('close',()=>{pendingPayment=null;if(lastFocus?.isConnected)lastFocus.focus({preventScroll:true});});
  dialog.addEventListener('click',event=>{const r=dialog.getBoundingClientRect();if(event.target===dialog&&(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom))close();});
  function shell(){const count=M.cartLines(data).reduce((s,p)=>s+p.quantity,0);return `<aside class="sidebar" id="sidebar"><a class="brand-lockup" href="index.html"><img src="assets/zeduc-space-logo.svg" alt="Logo ZEDUC-SP@CE" width="72" height="72"><span>ZEDUC-SP@CE<small>MON MIAM MIAM</small></span></a><div class="sidebar-caption">ESPACE ${M.roles[role].toUpperCase()}</div><nav aria-label="Navigation de votre espace">${menus[role].map(([id,label,i])=>`<a href="#${id}" ${id===view?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${id==='panier'&&count?`<b class="nav-count">${count}</b>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><a class="return-restaurant" href="index.html">← Retour au restaurant</a><div class="sidebar-person"><span class="avatar">${M.initials(user.name)}</span><span><strong>${E(user.name)}</strong><small>${M.roles[role]}</small></span><button data-action="logout" aria-label="Se déconnecter">${icon('logout')}</button></div></div></aside><div class="workspace-shell"><header class="workspace-header"><div><button class="sidebar-toggle" data-action="sidebar" aria-label="Ouvrir la navigation" aria-expanded="false">☰</button><span class="header-path">Mon Miam Miam <b>/</b> ${title()}</span></div><div class="header-right"><button type="button" class="text-btn" data-action="logout">Se déconnecter ↗</button></div></header><main id="workspace" tabindex="-1"><div class="page-heading"><div><span class="overline">KINSHASA · ULC ICAM</span><h1>${view==='accueil'?(role==='etudiant'?`Bonjour, ${E(user.name.split(' ')[0])}.`:'Le service, en un regard.'):title()}</h1></div><span class="today">${new Date().toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long',timeZone:'Africa/Kinshasa'})}</span></div>${renderContent()}</main><footer class="workspace-footer"><span>© 2026 ZEDUC-SP@CE · Le goût de se retrouver.</span><button data-action="about-demo">À propos de l’application</button></footer></div>`;}
  function statStrip(items){return `<div class="stat-strip">${items.map(([label,value,note])=>`<div><span>${label}</span><strong>${value}</strong><small>${note}</small></div>`).join('')}</div>`;}
  function productCard(p){const quantity=data.cart[p.id]||0;return `<article class="dish-card ${p.available?'':'dish-unavailable'}"><div class="dish-picture"><img src="assets/${E(p.image)}" alt="${E(p.name)}" width="300" height="230" loading="lazy">${p.daily?'<span class="dish-tag">AU MENU DU JOUR</span>':''}${!p.available?'<span class="unavailable-tag">ÉPUISÉ</span>':''}</div><div class="dish-body"><span class="dish-category">${E(p.category)}</span><h3>${E(p.name)}</h3><p>${E(p.description)}</p><div class="dish-bottom"><strong>${F(p.price)}</strong><button class="add-dish" data-action="add" data-id="${p.id}" ${!p.available?'disabled':''} aria-label="Ajouter ${E(p.name)} au panier">${quantity?`<span>${quantity}</span>`:icon('plus')}</button></div></div></article>`;}
  function overview(){if(role==='etudiant'){const active=ownOrders().find(o=>!['terminee','annulee'].includes(o.status));return `<section class="student-welcome"><div><span class="overline">UNE PAUSE BIEN MÉRITÉE</span><h2>ON S’OCCUPE<br>DE VOTRE FAIM.</h2><p>Votre pause entre deux cours, votre repas entre amis.<br>La carte du jour n’attend que vous.</p><a class="primary-btn" href="#menu">Choisir mon repas ${icon('arrow')}</a></div><img src="assets/gallery_img4-1-1.png" alt="Un burger généreux" width="529" height="584"></section><div class="overview-grid"><section class="panel current-order"><div class="section-line"><h2>Ma commande en cours</h2><a href="#commandes">Tout voir ↗</a></div>${active?`<div class="order-lead"><div><strong>${E(active.id)}</strong><span>${active.mode==='surplace'?'Sur place':'Livraison'} · ${F(active.total)}</span></div>${status(active)}</div>${progress(active)}<button class="quiet-btn" data-action="order" data-id="${active.id}">Voir le détail →</button>`:empty('Une envie ?','Votre prochaine commande apparaîtra ici.','#menu','Voir la carte')}</section><section class="loyalty-card"><span class="overline">MES PETITES HABITUDES, RÉCOMPENSÉES</span><strong>${user.points}<small>points</small></strong><p>${data.settings.rewardPoints} points = ${F(data.settings.rewardValue)} de réduction</p><a href="#fidelite">Ma carte de fidélité →</a><span class="loyalty-emblem">✦</span></section></div><div class="section-line roomy"><div><span class="overline">À PARTAGER… OU PAS</span><h2>Les envies du jour</h2></div><a href="#menu">Toute la carte ↗</a></div><div class="dish-grid">${data.products.filter(p=>p.daily&&!p.archived).slice(0,3).map(productCard).join('')}</div>`;}
    const s=M.stats(data,7);return `${statStrip([['Commandes en cours',data.orders.filter(o=>!['terminee','annulee'].includes(o.status)).length,'Tous les services'],['Ventes de la semaine',F(s.revenue),'Commandes terminées · 7 jours'],['Plats disponibles',data.products.filter(p=>p.available&&!p.archived).length,'Sur la carte du restaurant'],['Réclamations à suivre',data.complaints.filter(c=>c.status!=='resolue').length,'À traiter ou à valider']])}<div class="section-line roomy"><div><span class="overline">EN CUISINE, MAINTENANT</span><h2>Le fil des commandes</h2></div><a class="secondary-btn" href="#commandes">Toutes les commandes →</a></div>${orderTable(data.orders.filter(o=>!['terminee','annulee'].includes(o.status)).slice(0,6))}<div class="overview-grid roomy"><section class="panel"><div class="section-line"><h2>La semaine en chiffres</h2><a href="#statistiques">Détails ↗</a></div>${chart(7)}</section><section class="service-note"><span class="overline">LE BRIEF DU SERVICE</span><h2>CHAQUE COMMANDE<br>COMPTE.</h2><p>Confirmez les nouvelles commandes, signalez les plats épuisés et accompagnez chaque client jusqu’à la fin du service.</p><a href="#menu">Mettre à jour la carte →</a><div class="service-hours">${icon('clock')}<span>${E(data.settings.hours)}<small>Horaires indicatifs</small></span></div></section></div>`;}
  function progress(o){const steps=o.mode==='livraison'?['nouvelle','preparation','prete','livraison','terminee']:['nouvelle','preparation','prete','terminee'];const index=steps.indexOf(o.status);return `<ol class="order-progress">${steps.map((s,i)=>`<li class="${i<=index?'reached':''}"><span>${i<index?'✓':i+1}</span><small>${M.statuses[s]}</small></li>`).join('')}</ol>`;}
  function menuView(){if(role!=='etudiant')return staffMenu();const categories=['Tous',...new Set(data.products.filter(p=>!p.archived).map(p=>p.category))];const products=data.products.filter(p=>!p.archived&&(filters.category==='Tous'||p.category===filters.category)&&`${p.name} ${p.description}`.toLowerCase().includes(filters.q.toLowerCase()));return `<p class="page-intro">De quoi faire de votre pause un bon moment. Carte et prix indicatifs, en francs congolais.</p><div class="catalog-tools"><div class="category-tabs" aria-label="Catégories">${categories.map(c=>`<button data-category="${E(c)}" aria-pressed="${filters.category===c}">${E(c)}</button>`).join('')}</div><form novalidate class="search-form" id="search-form">${icon('search')}<label class="sr-only" for="catalog-search">Rechercher un plat</label><input id="catalog-search" name="q" value="${E(filters.q)}" placeholder="Une envie particulière ?"><button aria-label="Rechercher">→</button></form></div><div class="dish-grid">${products.map(productCard).join('')}</div>${!products.length?empty('Aucun plat trouvé','Essayez une autre recherche ou une autre catégorie.'):''}<a class="floating-bag" href="#panier">${icon('bag')} Mon panier <strong>${M.cartLines(data).reduce((n,p)=>n+p.quantity,0)}</strong></a>`;}
  function cartView(){const lines=M.cartLines(data);if(!lines.length)return empty('Votre panier attend ses premières envies.','Découvrez les plats du jour et composez votre repas.','#menu');const q=M.quote(data,user,checkout);return `<p class="page-intro">Encore un petit choix, et votre pause gourmande est prête à être organisée.</p><div class="checkout-layout"><section class="panel cart-products"><div class="section-line"><h2>Votre sélection</h2><a href="#menu">Continuer à choisir ↗</a></div>${lines.map(p=>`<article class="cart-line"><img src="assets/${E(p.image)}" alt="${E(p.name)}" width="88" height="88"><div><h3>${E(p.name)}</h3><p>${F(p.price)} par portion ${!p.available||p.archived?'<b class="error-text">· Indisponible</b>':''}</p><div class="quantity-controls"><button data-action="quantity" data-id="${p.id}" data-value="${p.quantity-1}" aria-label="Retirer une portion de ${E(p.name)}">−</button><span>${p.quantity}</span><button data-action="quantity" data-id="${p.id}" data-value="${p.quantity+1}" aria-label="Ajouter une portion de ${E(p.name)}">+</button></div></div><div class="cart-line-price"><strong>${F(p.price*p.quantity)}</strong><button data-action="quantity" data-id="${p.id}" data-value="0">Retirer</button></div></article>`).join('')}</section><section class="panel checkout-panel"><span class="overline">À VOTRE FAÇON</span><h2>Finaliser ma commande</h2><form novalidate id="checkout-form" class="form-stack"><div class="service-switch"><label><input type="radio" name="mode" value="surplace" ${checkout.mode==='surplace'?'checked':''}>Sur place</label><label><input type="radio" name="mode" value="livraison" ${checkout.mode==='livraison'?'checked':''}>Livraison</label></div><div id="fulfilment-fields">${checkout.mode==='surplace'?field('Heure d’arrivée','arrival',checkout.arrival||'13:00','time','required'):field('Adresse à Kinshasa','address',checkout.address??user.address,'text','required maxlength="180"')+field('Téléphone','phone',checkout.phone??user.phone,'tel','required pattern="[+0-9 ()-]{8,20}"')}</div><label class="field"><span>Une précision pour la cuisine ?</span><textarea style="resize:none" name="note" placeholder="Allergie, accompagnement…" maxlength="500">${E(checkout.note||'')}</textarea></label><fieldset class="payment-methods"><legend>Comment souhaitez-vous régler ?</legend><div class="payment-options">${[['cash',checkout.mode==='livraison'?'Espèces à la livraison':'Espèces au restaurant'],...Object.entries(M.paymentProviders)].map(([id,label])=>`<label class="payment-option"><input type="radio" name="payment" value="${id}" ${(checkout.payment||'cash')===id?'checked':''}><span><strong>${label}</strong><small>${id==='cash'?'À la réception du repas':'Mobile Money · sans débit réel'}</small></span><i class="payment-dot payment-${id}" aria-hidden="true"></i></label>`).join('')}</div></fieldset>${checkout.payment&&checkout.payment!=='cash'?`<div class="mobile-money-field">${field('Numéro Mobile Money','paymentPhone',checkout.paymentPhone??user.phone,'tel','required autocomplete="tel" inputmode="tel" placeholder="+243 …" maxlength="20" pattern="[+0-9 ()-]{9,20}"')}<p class="field-hint">Utilisez un numéro fictif. Aucun code PIN ne vous sera demandé.</p></div>`:''}<label class="check-row points-check"><input type="checkbox" name="usePoints" ${checkout.usePoints?'checked':''} ${user.points<data.settings.rewardPoints?'disabled':''}><span>Utiliser mes points<small>Solde : ${user.points} points</small></span></label><div class="bill"><div><span>Sous-total</span><span>${F(q.subtotal)}</span></div><div><span>Livraison</span><span>${F(q.delivery)}</span></div>${q.discount?`<div class="discount"><span>Fidélité · ${q.pointsUsed} points</span><span>− ${F(q.discount)}</span></div>`:''}<div class="bill-total"><strong>Total</strong><strong>${F(q.total)}</strong></div></div><div class="form-error" role="alert"></div><div class="points-preview">${icon('gift')}<p><strong>+${Math.floor((q.subtotal-q.discount)/data.settings.pointRate)} points à gagner</strong><span>Crédités après le service ou la livraison.<br>Hors frais de livraison, après remise.</span></p></div><button class="primary-btn" type="submit">${checkout.payment&&checkout.payment!=='cash'?'Continuer vers le paiement':'Valider la commande'} →</button><p class="field-hint">Aucun paiement n’est débité. La commande sera visible dans les espaces de gestion de ce navigateur.</p></form></section></div>`;}
  function completeCheckout(values) {
    const order=M.placeOrder(user.id,values);
    pendingPayment=null;checkout={mode:'surplace',usePoints:false};
    if(dialog.open)close();location.hash='commandes';render();orderDetail(order.id);
    toast('Votre commande a été enregistrée dans cet espace.');
  }
  function paymentPreview(values) {
    M.paymentDetails(values,false);
    const q=M.quote(M.read(),M.current(),values);
    pendingPayment={...values,expectedTotal:q.total};
    modal('Votre paiement Mobile Money',`<div class="payment-preview"><span class="demo-badge">SIMULATION UNIQUEMENT</span><h3>${E(M.paymentProviders[values.payment])}</h3><strong class="payment-amount">${F(q.total)}</strong><p>Numéro saisi<br><b>${E(values.paymentPhone)}</b></p></div><p class="modal-description">Aucune demande n’est envoyée sur un téléphone. Testez la confirmation ou le refus du paiement pour découvrir la suite du parcours.</p><div class="form-error" role="alert" id="payment-error"></div><div class="modal-actions"><button class="secondary-btn" data-action="payment-reject">Simuler un refus</button><button class="primary-btn" data-action="payment-confirm">Simuler la confirmation →</button></div><button class="text-button" data-action="close">← Revenir au panier</button>`);
  }
  function orderTable(orders){if(!orders.length)return empty('Aucune commande pour le moment.','Les commandes correspondant à votre sélection apparaîtront ici.',role==='etudiant'?'#menu':'');return `<div class="table-wrap"><table><thead><tr><th>Commande</th>${role!=='etudiant'?'<th>Client</th>':''}<th>Service</th><th>Montant</th><th>Statut</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${orders.map(o=>`<tr><td><strong>${E(o.id)}</strong><small>${M.date(o.date)}</small></td>${role!=='etudiant'?`<td>${E(person(o.userId))}<small>${o.items.reduce((n,p)=>n+p.quantity,0)} article(s)</small></td>`:''}<td>${o.mode==='livraison'?'Livraison':'Sur place'}<small>${o.mode==='surplace'?E(o.arrival||''):E(o.address?.split(',')[0]||'Kinshasa')}</small></td><td class="nowrap">${F(o.total)}</td><td>${status(o)}</td><td><button class="row-link" data-action="order" data-id="${o.id}">Voir ${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`;}
  function ordersView(){let orders=role==='etudiant'?ownOrders():data.orders;if(filters.status!=='toutes')orders=orders.filter(o=>filters.status==='encours'?!['terminee','annulee'].includes(o.status):o.status===filters.status);if(filters.q)orders=orders.filter(o=>`${o.id} ${person(o.userId)}`.toLowerCase().includes(filters.q.toLowerCase()));return `<p class="page-intro">${role==='etudiant'?'Retrouvez vos repas, suivez leur préparation et partagez votre expérience.':'Un suivi partagé, de la prise de commande jusqu’au service.'}</p><div class="catalog-tools"><div class="category-tabs">${[['toutes','Toutes'],['encours','En cours'],['terminee','Terminées'],['annulee','Annulées']].map(([v,l])=>`<button data-status="${v}" aria-pressed="${filters.status===v}">${l}</button>`).join('')}</div><form novalidate class="search-form" id="search-form">${icon('search')}<input aria-label="Rechercher une commande" name="q" placeholder="Numéro ou client…" value="${E(filters.q)}"><button aria-label="Rechercher">→</button></form></div>${orderTable(orders)}`;}
  function orderDetail(id){const o=data.orders.find(o=>o.id===id&&(role!=='etudiant'||o.userId===user.id));if(!o)return;const next={nouvelle:['preparation','Confirmer et préparer'],preparation:['prete','Marquer comme prête'],prete:o.mode==='livraison'?['livraison','Démarrer la livraison']:['terminee','Valider le service'],livraison:['terminee','Confirmer la livraison']}[o.status];modal(o.id,`<div class="modal-subline"><span>${E(person(o.userId))} · ${M.date(o.date)}</span>${status(o)}</div>${o.status!=='annulee'?progress(o):''}<div class="order-detail-lines">${o.items.map(p=>`<div><span>${p.quantity} × ${E(p.name)}</span><strong>${F(p.price*p.quantity)}</strong></div>`).join('')}<div><span>Livraison</span><strong>${F(o.delivery)}</strong></div>${o.discount?`<div><span>Remise fidélité</span><strong>− ${F(o.discount)}</strong></div>`:''}<div class="detail-total"><span>Total</span><strong>${F(o.total)}</strong></div></div><dl class="detail-meta"><dt>Service</dt><dd>${o.mode==='livraison'?`Livraison · ${E(o.address)}${o.phone?` · ${E(o.phone)}`:''}`:`Sur place à ${E(o.arrival||'12:30')}`}</dd><dt>Paiement</dt><dd>${E(o.payment)} · ${E({'confirme-simulation':'confirmé (simulation)','rembourse-simulation':'remboursé (simulation)','regle-simulation':'réglé (simulation)','a-regler':'à régler à réception'}[o.paymentStatus]||'non vérifié')}</dd>${o.note?`<dt>Note cuisine</dt><dd>${E(o.note)}</dd>`:''}</dl><div class="modal-actions">${role!=='etudiant'&&next?`<button class="primary-btn" data-action="transition" data-id="${o.id}" data-value="${next[0]}">${next[1]} →</button>`:''}${role!=='etudiant'&&['nouvelle','preparation'].includes(o.status)?`<button class="danger-btn" data-action="cancel-order" data-id="${o.id}">Annuler la commande</button>`:''}${role==='etudiant'?`<button class="secondary-btn" data-action="complaint-new" data-id="${o.id}">Signaler un problème</button>${o.status==='terminee'?`<button class="primary-btn" data-action="comment" data-id="${o.id}">Donner mon avis</button>`:''}`:''}</div>`);}
  function loyaltyView(){const log=data.pointsLog.filter(p=>p.userId===user.id);return `<p class="page-intro">Les bons moments laissent aussi des points. Retrouvez votre solde et chaque récompense.</p><div class="loyalty-layout"><section class="loyalty-card large"><span class="overline">MA CARTE MON MIAM MIAM</span><strong>${user.points}<small>points disponibles</small></strong><p>${E(user.name)} · ULC ICAM</p><div class="loyalty-stamps">${Array.from({length:10},(_,i)=>`<span class="${i<Math.min(10,Math.floor(user.points/10))?'filled':''}">✦</span>`).join('')}</div><a href="#panier">Utiliser mes points au panier →</a></section><section class="panel loyalty-explainer"><h2>Chaque repas compte.</h2><ol><li><span>01</span><div><h3>Commandez vos envies</h3><p>${F(data.settings.pointRate)} de repas réglé = 1 point.</p></div></li><li><span>02</span><div><h3>Retrouvez vos points</h3><p>Les points sont ajoutés après le service ou la livraison, une fois la commande terminée. Le calcul exclut les frais de livraison et tient compte des remises.</p></div></li><li><span>03</span><div><h3>Faites-vous plaisir</h3><p>${data.settings.rewardPoints} points donnent ${F(data.settings.rewardValue)} de réduction au panier.</p></div></li></ol><p class="field-hint">Règles du programme, modifiables par l’administrateur.</p></section></div><div class="section-line roomy"><h2>L’histoire de mes points</h2></div>${log.length?`<div class="table-wrap"><table><thead><tr><th>Mouvement</th><th>Date</th><th>Points</th></tr></thead><tbody>${log.map(p=>`<tr><td>${E(p.label)}</td><td>${M.date(p.date)}</td><td><strong class="${p.amount>0?'positive':'error-text'}">${p.amount>0?'+':''}${p.amount}</strong></td></tr>`).join('')}</tbody></table></div>`:empty('Vos premiers points arrivent bientôt.','Ils seront ajoutés après votre première commande terminée.')}`;}
  function referralView(){const refs=data.referrals.filter(r=>r.sponsorId===user.id);return `<p class="page-intro">Un bon repas, c’est encore meilleur à plusieurs. Invitez vos amis de l’ULC ICAM.</p><div class="referral-hero"><div><span class="overline">INVITEZ. PARTAGEZ. SAVOUREZ.</span><h2>LES BONNES ADRESSES<br>SE PARTAGENT.</h2><p>Votre ami utilise votre code à l’inscription. À sa première commande terminée, vous recevez ${data.settings.referralBonus} points.</p><div class="referral-code"><span>${E(user.code)}</span><button class="secondary-btn" data-action="copy-referral">Copier le code</button></div><button class="text-button" data-action="copy-link">Copier mon lien d’invitation ↗</button></div><div class="referral-mark">✦<small>À TABLE,<br>ENSEMBLE.</small></div></div>${statStrip([['Amis invités',refs.length,'Inscrits avec votre code'],['Parrainages récompensés',refs.filter(r=>r.rewarded).length,'Première commande terminée'],['Bonus par ami',`${data.settings.referralBonus} points`,'Règle du programme']])}<h2 class="roomy">Mes invitations</h2>${refs.length?`<div class="table-wrap"><table><thead><tr><th>Ami</th><th>Inscription</th><th>Suivi</th></tr></thead><tbody>${refs.map(r=>`<tr><td>${E(person(r.childId))}</td><td>${M.date(r.date)}</td><td><span class="status ${r.rewarded?'status-terminee':'status-nouvelle'}">${r.rewarded?'Récompense attribuée':'Première commande attendue'}</span></td></tr>`).join('')}</tbody></table></div>`:empty('Votre table peut encore s’agrandir.','Partagez votre code : vos amis apparaîtront ici dès leur inscription.')}`;}
  function eventView(){const events=data.promotions.filter(p=>p.active);const played=data.quiz.some(q=>q.userId===user.id&&q.day===new Date().toISOString().slice(0,10));return `<p class="page-intro">La vie du resto, les rendez-vous et les petites attentions. Programme proposé.</p><div class="poster-grid">${events.map(p=>poster(p,true)).join('')}</div>${!events.length?empty('Le programme se prépare.','Revenez bientôt découvrir les prochains rendez-vous.'):''}<section class="quiz-panel"><div><span class="overline">LA PAUSE QUIZ</span><h2>Connaissez-vous votre resto ?</h2><p>Une question, 5 points à gagner. Une participation par jour, uniquement dans cette local.</p></div><button class="primary-btn" data-action="quiz" ${played?'disabled':''}>${played?'Déjà joué aujourd’hui':'À moi de jouer →'}</button></section>`;}
  function poster(p,student=false){const joined=data.participations.some(x=>x.userId===user.id&&x.promoId===p.id);return `<article class="event-poster"><img src="assets/${E(p.image)}" alt="${E(p.title)}" loading="lazy"><div><span class="poster-label">${E(p.type)} · ${M.date(p.date)}</span><h2>${E(p.title)}</h2><p>${E(p.text)}</p>${student?`<button class="poster-link" data-action="join-event" data-id="${p.id}">${joined?'✓ Ajouté à mes rendez-vous':'Ça m’intéresse →'}</button>`:`<div class="poster-controls"><span>${p.active?'Visible':'Masquée'}</span><button data-action="promo-edit" data-id="${p.id}">Modifier</button><button data-action="promo-toggle" data-id="${p.id}">${p.active?'Masquer':'Afficher'}</button></div>`}</div></article>`;}
  function complaintsView(){const list=role==='etudiant'?data.complaints.filter(c=>c.userId===user.id):data.complaints;return `<div class="section-line"><p class="page-intro">${role==='etudiant'?'Un souci avec votre repas ? Parlons-en. Retrouvez ici le suivi de vos demandes.':'Écouter, répondre, puis valider la solution proposée au client.'}</p>${role==='etudiant'?'<button class="primary-btn" data-action="complaint-new">Nouvelle réclamation +</button>':''}</div><div class="complaint-list">${list.map(c=>`<article class="complaint-row"><div><span class="overline">${E(c.id)} · ${M.date(c.date)}</span><h3>${E(c.subject)}</h3><p>${role==='etudiant'?'Commande '+E(c.orderId):E(person(c.userId))+' · '+E(c.orderId)}</p></div><span class="status status-${c.status==='resolue'?'terminee':c.status==='validation'?'prete':'nouvelle'}">${complaintStatus[c.status]}</span><button class="row-link" data-action="complaint" data-id="${c.id}">${role==='etudiant'?'Consulter':'Traiter'} →</button></article>`).join('')}</div>${!list.length?empty('Tout va bien pour le moment.','Aucune réclamation à afficher.'):''}`;}
  function rankingView(){const since=Date.now()-filters.period*86400000;const counts=new Map();data.orders.filter(o=>o.status==='terminee'&&new Date(o.date)>=since).forEach(o=>counts.set(o.userId,(counts.get(o.userId)||0)+1));const rank=[...counts].sort((a,b)=>b[1]-a[1]).slice(0,10);return `<p class="page-intro">Le rendez-vous des habitués. Classement par nombre de commandes terminées.</p><div class="category-tabs ranking-tabs">${[[1,'Aujourd’hui'],[7,'Cette semaine'],[30,'Ce mois-ci']].map(([n,l])=>`<button data-period="${n}" aria-pressed="${filters.period===n}">${l}</button>`).join('')}</div>${rank.length?`<div class="ranking-list">${rank.map(([id,n],i)=>`<div class="ranking-row ${id===user.id?'is-you':''}"><span class="rank-number">${String(i+1).padStart(2,'0')}</span><span class="avatar">${M.initials(person(id))}</span><strong>${E(person(id))}${id===user.id?'<small>Vous</small>':''}</strong><span>${n} commande${n>1?'s':''}</span>${i<3?icon('award'):''}</div>`).join('')}</div>`:empty('Le classement attend ses gourmands.','Aucune commande terminée sur cette période.')}`;}
  function profileView(){return `<p class="page-intro">Les détails qui nous permettent de mieux préparer votre prochaine pause.</p><section class="panel profile-panel"><div class="profile-heading"><span class="avatar large-avatar">${M.initials(user.name)}</span><div><h2>${E(user.name)}</h2><p>Étudiant · ULC ICAM · Kinshasa</p></div></div><form novalidate id="profile-form" class="form-stack">${field('Nom complet','name',user.name,'text','required maxlength="80"')}<div class="form-grid">${field('Adresse e-mail','email',user.email,'email','required')}${field('Téléphone','phone',user.phone,'tel','required')}</div>${field('Adresse de livraison','address',user.address,'text','required maxlength="180"')}<div class="form-error" role="alert"></div><button class="primary-btn" type="submit">Enregistrer mes informations →</button></form></section>`;}
  function staffMenu(){const products=data.products.filter(p=>!p.archived);return `<div class="section-line"><p class="page-intro">${role==='admin'?'Composez la carte, ajustez les prix et choisissez les plats du jour.':'Mettez à jour les disponibilités et les suggestions du jour en un geste.'}</p>${role==='admin'?'<button class="primary-btn" data-action="product-new">Ajouter un plat +</button>':''}</div><div class="table-wrap"><table class="products-table"><thead><tr><th>Plat</th><th>Catégorie</th><th>Prix</th><th>Disponibilité</th><th>Menu du jour</th>${role==='admin'?'<th>Actions</th>':''}</tr></thead><tbody>${products.map(p=>`<tr><td><div class="table-product"><img src="assets/${E(p.image)}" width="54" height="54" alt=""><strong>${E(p.name)}</strong></div></td><td>${E(p.category)}</td><td class="nowrap">${F(p.price)}</td><td><button class="switch ${p.available?'on':''}" role="switch" aria-checked="${p.available}" aria-label="Disponibilité de ${E(p.name)}" data-action="availability" data-id="${p.id}"><span></span></button><small>${p.available?'Disponible':'Épuisé'}</small></td><td><button class="day-toggle ${p.daily?'selected':''}" aria-pressed="${p.daily}" data-action="daily" data-id="${p.id}" aria-label="Menu du jour : ${E(p.name)}">${p.daily?'✦ Oui':'+ Ajouter'}</button></td>${role==='admin'?`<td><button class="row-link" data-action="product-edit" data-id="${p.id}">Modifier</button><button class="text-danger" data-action="product-archive" data-id="${p.id}">Retirer</button></td>`:''}</tr>`).join('')}</tbody></table></div>`;}
  function teamView(){const staff=data.users.filter(u=>!u.archived&&(role==='admin'||['employe','gerant','admin'].includes(u.role)));return `<div class="section-line"><p class="page-intro">Une équipe, les bons accès. Comptes disponibles dans cet espace.</p><button class="primary-btn" data-action="staff-new">Ajouter un membre +</button></div><div class="table-wrap"><table><thead><tr><th>Membre</th><th>Rôle</th><th>Statut</th><th>Actions</th></tr></thead><tbody>${staff.map(u=>`<tr><td><div class="team-person"><span class="avatar">${M.initials(u.name)}</span><span><strong>${E(u.name)}</strong><small>${E(u.email)}</small></span></div></td><td>${M.roles[u.role]}</td><td><span class="status ${u.active?'status-terminee':'status-annulee'}">${u.active?'Actif':'Suspendu'}</span></td><td>${!u.id.startsWith('demo-')&&(role==='admin'||u.role==='employe')?`<button class="row-link" data-action="staff-edit" data-id="${u.id}">Modifier</button><button class="text-danger" data-action="staff-toggle" data-id="${u.id}">${u.active?'Suspendre':'Réactiver'}</button>${role==='admin'?`<button class="text-danger" data-action="account-archive" data-id="${u.id}">Archiver</button>`:''}`:'<small>Profil local</small>'}</td></tr>`).join('')}</tbody></table></div>`;}
  function promotionsView(){return `<div class="section-line"><p class="page-intro">Préparez les affiches qui apparaîtront dans l’espace étudiant.</p><button class="primary-btn" data-action="promo-new">Créer une affiche +</button></div><div class="poster-grid">${data.promotions.map(p=>poster(p)).join('')}</div>`;}
  function chart(days){const bins=Array.from({length:7},(_,i)=>{const day=new Date(Date.now()-(6-i)*86400000);const date=day.toISOString().slice(0,10);return {label:day.toLocaleDateString('fr-FR',{weekday:'short'}),value:data.orders.filter(o=>o.status==='terminee'&&o.date.slice(0,10)===date).reduce((n,o)=>n+o.total,0)};});const max=Math.max(...bins.map(b=>b.value),1);return `<div class="sales-chart" aria-label="Ventes terminées sur les sept derniers jours">${bins.map(b=>`<div class="chart-column"><span>${b.value?F(b.value):'0 FC'}</span><div class="bar-track"><div class="chart-bar" style="height:${Math.max(2,b.value/max*100)}%"></div></div><small>${b.label}</small></div>`).join('')}</div>`;}
  function statisticsView(){const s=M.stats(data,filters.period),top=new Map();s.done.forEach(o=>o.items.forEach(p=>{const entry=top.get(p.name)||{count:0,total:0};entry.count+=p.quantity;entry.total+=p.price*p.quantity;top.set(p.name,entry);}));return `<div class="section-line"><p class="page-intro">Chiffres calculés à partir des commandes enregistrées. Les commandes annulées sont exclues des ventes.</p><label class="period-select">Période <select id="stats-period"><option value="7" ${filters.period===7?'selected':''}>7 derniers jours</option>${role!=='employe'?`<option value="30" ${filters.period===30?'selected':''}>30 derniers jours</option>`:''}</select></label></div>${statStrip([['Ventes terminées',F(s.revenue),`${s.done.length} commandes servies`],['Commandes reçues',s.orders.length,`${filters.period} derniers jours`],['Panier moyen',F(s.average),'Sur les commandes terminées'],['Commandes à suivre',s.pending,'En cours sur cette période']])}<section class="panel roomy"><div class="section-line"><h2>Le rythme de la semaine</h2><span class="field-hint">Ventes quotidiennes · 7 jours</span></div>${chart(7)}</section><div class="section-line roomy"><h2>Les plats les plus commandés</h2></div><div class="table-wrap"><table><thead><tr><th>Plat</th><th>Portions servies</th><th>Ventes avant remise</th></tr></thead><tbody>${[...top].sort((a,b)=>b[1].count-a[1].count).map(([name,p])=>`<tr><td>${E(name)}</td><td>${p.count}</td><td>${F(p.total)}</td></tr>`).join('')||'<tr><td colspan="3">Aucune vente terminée sur cette période.</td></tr>'}</tbody></table></div>`;}
  function settingsView(){const s=data.settings;return `<p class="page-intro">Les règles communes au restaurant, au programme de fidélité et à la livraison.</p><form novalidate id="settings-form" class="panel settings-form form-stack"><h2>Le restaurant</h2><div class="form-grid">${field('Nom','restaurant',s.restaurant,'text','required')}${field('Ville','city',s.city,'text','required')}</div>${field('Horaires affichés','hours',s.hours,'text','required')}<h2 class="form-section-title">Fidélité & parrainage</h2><div class="form-grid">${field('Dépense pour gagner 1 point (FC)','pointRate',s.pointRate,'number','min="1" step="1" required')}${field('Points nécessaires par remise','rewardPoints',s.rewardPoints,'number','min="1" step="1" required')}${field('Valeur de la remise (FC)','rewardValue',s.rewardValue,'number','min="1" step="1" required')}${field('Bonus de parrainage (points)','referralBonus',s.referralBonus,'number','min="0" step="1" required')}</div><h2 class="form-section-title">Livraison</h2>${field('Frais de livraison simulés (FC)','deliveryFee',s.deliveryFee,'number','min="0" step="1" required')}<div class="form-error" role="alert"></div><button class="primary-btn" type="submit">Enregistrer les paramètres →</button><p class="field-hint">Ces règles s’appliquent aux prochaines commandes. Les anciennes commandes conservent leurs montants.</p></form>`;}
  function renderContent(){return ({accueil:overview,menu:menuView,panier:cartView,commandes:ordersView,fidelite:loyaltyView,parrainage:referralView,evenements:eventView,reclamations:complaintsView,classement:rankingView,profil:profileView,equipe:teamView,promotions:promotionsView,statistiques:statisticsView,parametres:settingsView}[view]||overview)();}
  function render(){data=M.read();user=M.current();if(!user||user.role!==role){root.replaceChildren();location.replace('connexion.html');return;}view=location.hash.slice(1)||'accueil';if(!menus[role].some(m=>m[0]===view))view='accueil';root.innerHTML=shell();document.title=`${title()} · Mon Miam Miam`;}
  function complaintForm(orderId=''){const orders=ownOrders();if(!orders.length){toast('Passez d’abord une commande pour pouvoir la signaler.');return;}modal('Parlons de votre commande',`<form novalidate id="complaint-form" class="form-stack"><label class="field"><span>Commande concernée</span><select name="orderId" required>${orders.map(o=>`<option value="${o.id}" ${o.id===orderId?'selected':''}>${E(o.id)} · ${M.date(o.date)}</option>`).join('')}</select></label>${field('Sujet','subject','','text','required maxlength="100"')}<label class="field"><span>Que s’est-il passé ?</span><textarea style="resize:none" name="message" required minlength="10" maxlength="2000" placeholder="Expliquez-nous la situation…"></textarea></label><div class="form-error" role="alert"></div><button class="primary-btn" type="submit">Envoyer ma réclamation →</button></form>`);}
  function complaintDetail(id){const c=data.complaints.find(c=>c.id===id&&(role!=='etudiant'||c.userId===user.id));if(!c)return;modal(c.subject,`<div class="modal-subline"><span>${E(c.orderId)} · ${E(person(c.userId))}</span><span class="status">${complaintStatus[c.status]}</span></div><div class="message-bubble"><span>Message du client · ${M.date(c.date)}</span><p>${E(c.message)}</p></div>${role==='etudiant'?`<div class="message-bubble team-message"><span>L’équipe Mon Miam Miam</span><p>${c.status==='resolue'?E(c.reply):'Votre demande est en cours de traitement. La réponse validée par le responsable apparaîtra ici.'}</p></div>`:`<form novalidate id="reply-form" class="form-stack"><input type="hidden" name="id" value="${c.id}"><label class="field"><span>Réponse ${role==='employe'?'à faire valider':'au client'}</span><textarea style="resize:none" name="reply" required minlength="10" maxlength="2000">${E(c.reply)}</textarea></label><div class="form-error" role="alert"></div><div class="modal-actions"><button class="primary-btn" type="submit" name="approve" value="${role==='employe'?'no':'yes'}">${role==='employe'?'Proposer cette réponse':'Valider et résoudre'} →</button>${role!=='employe'&&c.status==='validation'?`<button class="secondary-btn" type="button" data-action="complaint-reopen" data-id="${c.id}">Renvoyer à l’équipe</button>`:''}</div></form>`}`);}
  const imageChoices=['burger-5.png','shushi-1.png','exploring_img-1.png','fried_rice-1.png','mexican_Tacos_Pastor-1.png','italian_Spaghetti_Carbonara-1.png','classic_cheez_pizza-1-1.png','Mango-Sorbet-1.png','Red-Velvet-Cupcakes-1.png','gallery_img2-1-1.png','make_reservation-1.png','pondu-fufu.webp','liboke-mbisi.webp','poulet-moambe.webp'];
  const imageNames=['Burger','Brochettes','Pizza du jardin','Riz sauté','Tacos','Spaghetti','Pizza classique','Sorbet','Cupcake','Milkshake','Salle du restaurant','Pondu, fufu et poisson','Liboké ya mbisi','Poulet à la moambe'];
  function imageSelect(selected){return `<label class="field"><span>Photo du plat</span><select name="image">${imageChoices.map((image,i)=>`<option value="${image}" ${image===selected?'selected':''}>${imageNames[i]}</option>`).join('')}</select></label>`;}
  function productForm(id){const p=data.products.find(p=>p.id===id)||{name:'',price:15000,category:'Plats',description:'',image:'burger-5.png',available:true,daily:false};modal(id?'Modifier le plat':'Ajouter un plat',`<form novalidate id="product-form" class="form-stack"><input type="hidden" name="id" value="${E(id||'')}">${field('Nom du plat','name',p.name,'text','required maxlength="80"')}<div class="form-grid">${field('Prix en francs congolais','price',p.price,'number','min="1" step="1" required')}<label class="field"><span>Catégorie</span><select name="category">${options(['Burgers','Grillades','Pizzas','Plats','Plats congolais','Desserts','Boissons'],p.category)}</select></label></div><label class="field"><span>Description</span><textarea style="resize:none" name="description" required maxlength="300">${E(p.description)}</textarea></label>${imageSelect(p.image)}<div class="form-grid"><label class="check-row"><input type="checkbox" name="available" ${p.available?'checked':''}>Disponible</label><label class="check-row"><input type="checkbox" name="daily" ${p.daily?'checked':''}>Au menu du jour</label></div><div class="form-error" role="alert"></div><button class="primary-btn" type="submit">Enregistrer le plat →</button></form>`);}
  function staffForm(id){const u=data.users.find(u=>u.id===id)||{name:'',email:'',role:'employe'};modal(id?'Modifier le compte':'Un nouveau membre dans l’équipe',`<form novalidate id="staff-form" class="form-stack"><input type="hidden" name="id" value="${E(id||'')}">${field('Nom complet','name',u.name,'text','required maxlength="80"')}${field('Adresse e-mail fictive','email',u.email,'email','required')}<label class="field"><span>Rôle</span><select name="role">${(role==='admin'?['employe','gerant','etudiant']:['employe']).map(r=>`<option value="${r}" ${u.role===r?'selected':''}>${M.roles[r]}</option>`).join('')}</select></label>${field(id?'Nouveau mot de passe (facultatif)':'Mot de passe','password','','password',`${id?'':'required'} minlength="8" autocomplete="new-password"`)}<p class="field-hint">8 caractères minimum, une majuscule et un chiffre. Le compte reste local à ce navigateur ; aucune invitation n’est envoyée.</p><div class="form-error" role="alert"></div><button class="primary-btn" type="submit">${id?'Enregistrer':'Créer le compte'} →</button></form>`);}
  function promoForm(id){const p=data.promotions.find(p=>p.id===id)||{title:'',text:'',image:'burger-5.png',type:'Offre',date:new Date().toISOString().slice(0,10),active:true};modal(id?'Modifier l’affiche':'Créer une affiche',`<form novalidate id="promo-form" class="form-stack"><input type="hidden" name="id" value="${E(id||'')}">${field('Titre','title',p.title,'text','required maxlength="70"')}<div class="form-grid"><label class="field"><span>Type</span><select name="type">${options(['Offre','Événement'],p.type)}</select></label>${field('Date','date',p.date,'date','required')}</div><label class="field"><span>Texte de l’affiche</span><textarea style="resize:none" name="text" required maxlength="300">${E(p.text)}</textarea></label>${imageSelect(p.image)}<label class="check-row"><input type="checkbox" name="active" ${p.active?'checked':''}>Visible dans l’espace étudiant</label><div class="form-error" role="alert"></div><button class="primary-btn" type="submit">Enregistrer l’affiche →</button></form>`);}
  function confirmAction(title,text,action,id){modal(title,`<p class="modal-description">${E(text)}</p><div class="modal-actions"><button class="secondary-btn" data-action="close">Revenir</button><button class="danger-btn" data-action="${action}" data-id="${id}">${action==='confirm-cancel'?'Annuler la commande':action==='confirm-staff-toggle'?'Suspendre le compte':action==='confirm-account-archive'?'Archiver le compte':'Retirer le plat'}</button></div>`);}
  async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copié. À vous de partager !');}catch{modal('À partager',`<p>Copiez le texte ci-dessous.</p><input class="copy-field" readonly value="${E(text)}" aria-label="Texte à copier">`);}}
  async function action(button){const a=button.dataset.action,id=button.dataset.id;try{
    M.requireRole(user,[role]);
    if(a==='close'){close();return;}
    if(a==='payment-reject'){pendingPayment=null;close();const error=document.querySelector('#checkout-form .form-error');error.textContent='Paiement refusé dans la simulation. Votre panier et vos points sont conservés. Réessayez ou choisissez un autre moyen de paiement.';error.scrollIntoView({block:'center'});toast('Paiement refusé · aucune commande créée.');return;}
    if(a==='payment-confirm'){if(!pendingPayment)return;button.disabled=true;try{completeCheckout({...pendingPayment,paymentConfirmed:true});}catch(error){document.querySelector('#payment-error').textContent=error.message;button.disabled=false;}return;}

    if(a==='sidebar'){const open=document.body.classList.toggle('sidebar-open');button.setAttribute('aria-expanded',String(open));button.setAttribute('aria-label',open?'Fermer la navigation':'Ouvrir la navigation');return;}
    if(a==='logout'){M.logout();location.href='connexion.html';return;}
    if(a==='add'){M.addToCart(id);render();toast('Ajouté à votre panier.');return;}
    if(a==='quantity'){M.setQuantity(id,Number(button.dataset.value));render();return;}
    if(a==='order'){orderDetail(id);return;}
    if(a==='transition'){M.transition(user.id,id,button.dataset.value);close();render();toast('Le statut de la commande a été mis à jour.');return;}
    if(a==='cancel-order'){confirmAction('Annuler cette commande ?', 'Les points de fidélité utilisés seront rendus au client. Cette commande ne pourra plus être préparée.','confirm-cancel',id);return;}
    if(a==='confirm-cancel'){M.transition(user.id,id,'annulee');close();render();toast('Commande annulée.');return;}
    if(a==='complaint-new'){complaintForm(id);return;}
    if(a==='complaint'){complaintDetail(id);return;}
    if(a==='complaint-reopen'){M.requireRole(user,['gerant','admin']);const d=M.read();d.complaints.find(c=>c.id===id).status='ouverte';M.save(d);close();render();toast('La demande a été renvoyée à l’équipe.');return;}
    if(a==='availability'||a==='daily'){M.toggleProduct(user.id,id,a==='availability'?'available':'daily');render();return;}
    if(a==='product-new'||a==='product-edit'){productForm(id);return;}
    if(a==='product-archive'){confirmAction('Retirer ce plat de la carte ?', 'Le plat ne sera plus commandable. Les commandes déjà passées conservent leur détail.','confirm-product-archive',id);return;}
    if(a==='confirm-product-archive'){M.archiveProduct(user.id,id);close();render();toast('Le plat a été retiré de la carte.');return;}
    if(a==='staff-new'||a==='staff-edit'){staffForm(id);return;}
    if(a==='staff-toggle'){const member=data.users.find(u=>u.id===id);if(member.active){confirmAction('Suspendre ce compte ?', 'Le membre ne pourra plus se connecter. Vous pourrez réactiver son compte depuis cette liste.','confirm-staff-toggle',id);}else{M.toggleStaff(user.id,id);render();toast('Le compte a été réactivé.');}return;} if(a==='confirm-staff-toggle'){M.toggleStaff(user.id,id);close();render();toast('Le compte a été suspendu.');return;}
    if(a==='account-archive'){confirmAction('Archiver ce compte ?', 'Le compte ne pourra plus se connecter et quittera cette liste. Son historique de commandes reste conservé.','confirm-account-archive',id);return;}
    if(a==='confirm-account-archive'){M.archiveAccount(user.id,id);close();render();toast('Le compte a été archivé.');return;}
    if(a==='promo-new'||a==='promo-edit'){promoForm(id);return;}
    if(a==='promo-toggle'){M.requireRole(user,['admin']);const d=M.read(),p=d.promotions.find(p=>p.id===id);p.active=!p.active;M.save(d);render();return;}
    if(a==='copy-referral'){await copy(user.code);return;}
    if(a==='copy-link'){await copy(new URL(`inscription.html?parrain=${encodeURIComponent(user.code)}`,location.href).href);return;}
    if(a==='join-event'){const d=M.read(),index=d.participations.findIndex(p=>p.userId===user.id&&p.promoId===id);if(index<0)d.participations.push({userId:user.id,promoId:id});else d.participations.splice(index,1);M.save(d);render();toast(index<0?'Ajouté à vos rendez-vous.':'Rendez-vous retiré.');return;}
    if(a==='quiz'){modal('La pause quiz',`<form novalidate id="quiz-form" class="form-stack"><p class="quiz-question">Dans quelle ville se retrouve la communauté Mon Miam Miam ?</p>${['Kinshasa','Douala','Brazzaville'].map(city=>`<label class="quiz-option"><input type="radio" name="answer" value="${city}" required>${city}</label>`).join('')}<div class="form-error" role="alert"></div><button class="primary-btn" type="submit">Valider ma réponse →</button></form>`);return;}
    if(a==='comment'){const previous=data.comments.find(c=>c.userId===user.id&&c.orderId===id);modal('Comment était votre repas ?',`<form novalidate id="comment-form" class="form-stack"><input type="hidden" name="orderId" value="${id}"><label class="field"><span>Votre note</span><select name="rating">${[5,4,3,2,1].map(n=>`<option value="${n}" ${previous?.rating===n?'selected':''}>${n} / 5</option>`).join('')}</select></label><label class="field"><span>Votre commentaire</span><textarea style="resize:none" name="message" required minlength="5" maxlength="1000">${E(previous?.message||'')}</textarea></label><div class="form-error" role="alert"></div><button class="primary-btn" type="submit">Enregistrer mon avis →</button></form>`);return;}
    if(a==='about-demo'){modal('À propos de Mon Miam Miam',`<p class="modal-description">Cette version est entièrement front-end. Les profils, prix, horaires et commandes sont fictifs. Vos actions sont enregistrées uniquement dans ce navigateur.</p><p class="modal-description">La connexion simule les espaces sans constituer une sécurité serveur. Les mots de passe des comptes créés sont dérivés localement ; utilisez uniquement des informations fictives. Aucun message, paiement ou ordre réel n’est transmis.</p><p class="modal-description">Les accès sont attribués selon votre compte. Contactez le responsable du restaurant pour un accès à l’équipe.</p><a class="primary-btn" href="connexion.html">Revenir à la connexion →</a>`);return;}
  }catch(error){toast(error.message);}}
  document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(button){event.preventDefault();action(button);return;}const category=event.target.closest('[data-category]');if(category){filters.category=category.dataset.category;render();}const statusButton=event.target.closest('[data-status]');if(statusButton){filters.status=statusButton.dataset.status;render();}const period=event.target.closest('[data-period]');if(period){filters.period=Number(period.dataset.period);render();}});
  function rememberCheckout(form){checkout={...checkout,...Object.fromEntries(new FormData(form)),usePoints:form.elements.usePoints.checked};}
  document.addEventListener('input',event=>{const form=event.target.closest('#checkout-form');if(form)rememberCheckout(form);});
  document.addEventListener('change',event=>{if(event.target.id==='stats-period'){filters.period=Number(event.target.value);render();}if(event.target.closest('#checkout-form')&&['mode','usePoints','payment'].includes(event.target.name)){const form=event.target.closest('form'),name=event.target.name,value=event.target.value;rememberCheckout(form);render();const control=[...document.querySelectorAll('#checkout-form input')].find(x=>x.name===name&&x.value===value);control?.focus({preventScroll:true});}});
  document.addEventListener('submit',async event=>{
    const form=event.target;if(!(form instanceof HTMLFormElement))return;event.preventDefault();const values=Object.fromEntries(new FormData(form)),error=form.querySelector('.form-error'),submitter=event.submitter; if(error)error.textContent='';if(submitter)submitter.disabled=true;
    try{
      M.requireRole(user,[role]);
      if(form.getAttribute('id')==='search-form'){filters.q=values.q.trim();render();return;}
      if(form.getAttribute('id')==='checkout-form'){checkout={...values,usePoints:form.elements.usePoints.checked};if(checkout.payment!=='cash')paymentPreview(checkout);else completeCheckout(checkout);return;}
      if(form.getAttribute('id')==='profile-form'){const d=M.read();if(d.users.some(u=>u.id!==user.id&&u.email.toLowerCase()===values.email.trim().toLowerCase()))throw new Error('Cette adresse est déjà utilisée.');const u=d.users.find(u=>u.id===user.id);Object.assign(u,{name:values.name.trim(),email:values.email.trim().toLowerCase(),phone:values.phone.trim(),address:values.address.trim()});M.save(d);render();toast('Vos informations ont été enregistrées.');return;}
      if(form.getAttribute('id')==='complaint-form'){M.complaint(user.id,values);close();location.hash='reclamations';render();toast('Votre réclamation a été enregistrée.');return;}
      if(form.getAttribute('id')==='reply-form'){M.replyComplaint(user.id,values.id,values.reply,submitter?.value==='yes');close();render();toast(role==='employe'?'Réponse proposée au responsable.':'Réponse validée et visible par le client.');return;}
      if(form.getAttribute('id')==='product-form'){M.saveProduct(user.id,{id:values.id||undefined,name:values.name.trim(),category:values.category,price:Number(values.price),description:values.description.trim(),image:values.image,available:form.elements.available.checked,daily:form.elements.daily.checked});close();render();toast('La carte a été mise à jour.');return;}
      if(form.getAttribute('id')==='staff-form'){await M.saveStaff(user.id,{id:values.id||undefined,name:values.name.trim(),email:values.email.trim().toLowerCase(),role:values.role,password:values.password});close();render();toast('Le compte de l’équipe a été enregistré.');return;}
      if(form.getAttribute('id')==='promo-form'){M.requireRole(user,['admin']);const d=M.read(),p={id:values.id||M.uid('affiche'),title:values.title.trim(),text:values.text.trim(),image:values.image,type:values.type,date:values.date,active:form.elements.active.checked};const existing=d.promotions.find(x=>x.id===p.id);if(existing)Object.assign(existing,p);else d.promotions.push(p);M.save(d);close();render();toast('L’affiche a été enregistrée.');return;}
      if(form.getAttribute('id')==='settings-form'){M.requireRole(user,['admin']);const d=M.read();for(const key of ['pointRate','rewardPoints','rewardValue','referralBonus','deliveryFee']){const n=Number(values[key]);if(!Number.isInteger(n)||n<(['referralBonus','deliveryFee'].includes(key)?0:1))throw new Error('Les valeurs doivent être des entiers valides.');d.settings[key]=n;}for(const key of ['restaurant','city','hours'])d.settings[key]=values[key].trim();M.save(d);render();toast('Les paramètres ont été enregistrés.');return;}
      if(form.getAttribute('id')==='quiz-form'){const d=M.read(),day=new Date().toISOString().slice(0,10);if(d.quiz.some(q=>q.userId===user.id&&q.day===day))throw new Error('Vous avez déjà participé aujourd’hui.');const won=values.answer==='Kinshasa';d.quiz.push({userId:user.id,day,won});if(won){d.users.find(u=>u.id===user.id).points+=5;d.pointsLog.unshift({id:M.uid('pt'),userId:user.id,date:M.iso(),amount:5,label:'La pause quiz'});}M.save(d);close();render();toast(won?'Bien joué ! 5 points ajoutés à votre carte.':'La réponse était Kinshasa. Rendez-vous demain !');return;}
      if(form.getAttribute('id')==='comment-form'){const d=M.read();if(!d.orders.some(o=>o.id===values.orderId&&o.userId===user.id&&o.status==='terminee'))throw new Error('Votre commande doit être terminée avant de donner un avis.');const comment={userId:user.id,orderId:values.orderId,rating:Number(values.rating),message:values.message.trim(),date:M.iso()};const old=d.comments.find(c=>c.userId===user.id&&c.orderId===values.orderId);if(old)Object.assign(old,comment);else d.comments.push(comment);M.save(d);close();render();toast('Merci, votre avis a été enregistré dans la local.');return;}
    }catch(e){if(error){error.textContent=e.message;error.scrollIntoView({block:'nearest'});}else toast(e.message);}finally{if(submitter?.isConnected)submitter.disabled=false;}
  });
  window.addEventListener('hashchange',()=>{filters={q:'',category:'Tous',status:'toutes',period:7};document.body.classList.remove('sidebar-open');render();document.querySelector('#workspace').focus({preventScroll:true});window.scrollTo(0,0);});
  window.addEventListener('storage',event=>{if(event.key===M.KEY&&!dialog.open&&!document.activeElement?.matches('input,textarea,select'))render();});
  document.addEventListener('keydown',event=>{if(event.key==='Escape')document.body.classList.remove('sidebar-open');});
  render();
})();
